import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.DPwiCy1i.js";const u=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"sturn","text":"agents murmurate, not merge","tagline":"Ephemeral coordination engine — claims/ops/topics over VCS state","actions":[{"theme":"brand","text":"Get started","link":"/tutorials/getting-started"},{"theme":"alt","text":"Why sturn?","link":"/explanation/architecture"}]},"features":[{"title":"Workspaces are pointers","details":"No clones, no worktrees, no checkout materialization. refs/sturn/ws/<name> is a ref to a commit — a thousand agent workspaces cost nothing."},{"title":"Conflicts prevented, not found","details":"Claims publish advisory locks before edits happen. Contenders learn in milliseconds on the claims topic, not at a three-way merge twenty minutes later."},{"title":"The bus is a cache","details":"Ops live in refs/sturn/wal/* as ordinary git objects — replicated by plain push/fetch, signed by git's own machinery. The pub/sub layer accelerates; it never owns truth."},{"title":"Continuous review","details":"Ops stream to reviewers as they land. snap is the only thing that becomes a commit — the PR stops being a gate and becomes a packaging format."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),n={name:"index.md"};function i(s,e,d,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<div style="display:none;" hidden data-nosnippet>Are you an LLM? View /sturn/llms.txt for optimized Markdown documentation, or /sturn/llms-full.txt for full documentation bundle</div><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>Sturn is ephemeral coordination for agents working one repo: claims, ops, topics, and asks appended to a git-native WAL (<code>refs/sturn/wal/*</code>), with workspaces as zero-cost pointers (<code>refs/sturn/ws/*</code>) and a rebuildable pub/sub bus for live stream.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><p>Parallel agents collide at merge time — twenty minutes into a three-way merge you learn two of them edited the same file. Sturn moves coordination <em>before</em> the edit: claims publish advisory locks in milliseconds, ops stream to reviewers continuously, and <code>snap</code> is the only thing that becomes a commit. The WAL rides ordinary git push/fetch, so coordination replicates with zero new infrastructure.</p><h2 id="boundary" tabindex="-1">Boundary <a class="header-anchor" href="#boundary" aria-label="Permalink to &quot;Boundary&quot;">​</a></h2><ul><li><strong>Owns:</strong> live claims, ops, topics, asks — the moment-of-work coordination layer.</li><li><strong>Doesn&#39;t own:</strong> durable work memory (<a href="https://9aia.com/myco/" target="_blank" rel="noreferrer">myco</a>), code memory (<a href="https://9aia.com/kuda/" target="_blank" rel="noreferrer">kuda</a>), distribution (<a href="https://9aia.com/tamias/" target="_blank" rel="noreferrer">tamias</a>), orchestration (<a href="https://9aia.com/peregrin/" target="_blank" rel="noreferrer">peregrin</a>).</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to…</th><th>Go to</th></tr></thead><tbody><tr><td>Run your first swarm — two agents, one repo</td><td><a href="/sturn/tutorials/getting-started.html">Tutorial</a></td></tr><tr><td>Do a task (hydrate, mount, daemon ops)</td><td><a href="/sturn/how-to/">How-to</a></td></tr><tr><td>Understand the design (WAL, model, no-CRDT)</td><td><a href="/sturn/explanation/">Explanation</a></td></tr><tr><td>Look up an op, verb, or config field</td><td><a href="/sturn/reference/">Reference</a></td></tr></tbody></table>',9)])])}const p=t(n,[["render",i]]);export{u as __pageData,p as default};
